// Menus, categories, products, modifiers, menu import and the public menu.
// Owner: Agent B1 (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { idempotencyKey, optionalText, text, uuid } from './common';
import type { SocialLinks } from './social-links';

export const catalogContractsVersion = 2 as const;

/** EU-14 style allergen keys used by the menu editor (free text is still accepted, ≤ 40 chars). */
export const ALLERGENS = ['milk', 'eggs', 'fish', 'shellfish', 'tree_nuts', 'peanuts', 'wheat', 'gluten', 'soy', 'sesame', 'mustard', 'celery', 'sulphites', 'lupin', 'molluscs'] as const;
export const DIETARY_TAGS = ['vegetarian', 'vegan', 'halal', 'gluten_free', 'dairy_free', 'spicy', 'kids'] as const;

const tag = z.string().trim().min(1).max(40);
const tags = (max: number) => z.array(tag).max(max);
const priceMinor = z.number().int().min(0).max(100_000_000);

export const categoryInput = z.object({
  name: text(80),
  nameAr: optionalText(80),
  description: optionalText(500),
  defaultStation: optionalText(40),
  menuId: uuid.optional(),
  isActive: z.boolean().optional(),
});
export const categoryUpdate = categoryInput.partial().omit({ menuId: true });
export const categoryReorder = z.object({ ids: z.array(uuid).min(1).max(500) });

export const productInput = z.object({
  categoryId: uuid,
  name: text(120),
  nameAr: optionalText(120),
  description: optionalText(1000),
  descriptionAr: optionalText(1000),
  priceMinor,
  costMinor: priceMinor.nullable().optional(),
  station: text(40).optional(),
  prepMinutes: z.number().int().min(0).max(600).nullable().optional(),
  spiceLevel: z.number().int().min(0).max(3).optional(),
  dietary: tags(30).optional(),
  allergens: tags(30).optional(),
  ingredients: tags(60).optional(),
  calories: z.number().int().min(0).max(20000).nullable().optional(),
  imageUrl: z.url().max(1000).nullable().optional(),
  isActive: z.boolean().optional(),
  trackStock: z.boolean().optional(),
  sortOrder: z.number().int().min(0).max(100000).optional(),
  externalRef: optionalText(120),
});
export type ProductInput = z.infer<typeof productInput>;
/** Edits carry the version the editor loaded; a mismatch is a 409 `stale_product`. */
export const productUpdate = productInput.partial().extend({ version: z.number().int().min(0) });
export type ProductUpdate = z.infer<typeof productUpdate>;

export const productBranchSetting = z.object({
  /** Offered at this branch (branch assignment; false hides the dish there). The temporary 86 is POST …/availability. */
  isAvailable: z.boolean().optional(),
  priceOverrideMinor: priceMinor.nullable().optional(),
  stockQty: z.number().int().min(0).max(1_000_000).nullable().optional(),
});
/** Quick 86 / restore (sold out today). The full request with `until` and `reason` is soldOutRequest (operations.ts). */
export const availabilityToggle = z.object({ branchId: uuid, available: z.boolean() });

export const modifierGroupInput = z.object({
  name: text(80),
  nameAr: optionalText(80),
  minSelect: z.number().int().min(0).max(20).default(0),
  maxSelect: z.number().int().min(1).max(20).default(1),
  isActive: z.boolean().optional(),
}).refine((g) => g.minSelect <= g.maxSelect, { message: 'minSelect must not exceed maxSelect', path: ['minSelect'] });
export const modifierGroupUpdate = z.object({
  name: text(80).optional(),
  nameAr: optionalText(80),
  minSelect: z.number().int().min(0).max(20).optional(),
  maxSelect: z.number().int().min(1).max(20).optional(),
  isActive: z.boolean().optional(),
});
export const modifierOptionInput = z.object({
  name: text(80),
  nameAr: optionalText(80),
  priceDeltaMinor: priceMinor.default(0),
  isDefault: z.boolean().optional(),
  isAvailable: z.boolean().optional(),
  sortOrder: z.number().int().min(0).max(1000).optional(),
});
export const modifierOptionUpdate = modifierOptionInput.partial();
export const productModifierAssignment = z.object({ groupIds: z.array(uuid).max(20) });

// ---------------------------------------------------------------------------
// Import (§8 MODULE_CONTRACTS): CSV, POS adapters (Foodics/Odoo) and AI drafts
// ---------------------------------------------------------------------------
export const IMPORT_MAX_ROWS = 300;
export const menuImportRow = z.object({
  externalId: z.string().trim().max(120).optional(),
  name: z.string().max(200),
  nameAr: z.string().max(200).optional(),
  category: z.string().max(200),
  description: z.string().max(2000).optional(),
  priceMinor: z.number(),
  station: z.string().max(200).optional(),
  allergens: z.array(z.string().max(200)).max(100).optional(),
  available: z.boolean().optional(),
});
export type MenuImportRow = z.infer<typeof menuImportRow>;
export const menuImportRequest = z.object({
  rows: z.array(menuImportRow).min(1).max(IMPORT_MAX_ROWS).optional(),
  /** Alternative to rows: a CSV document (legacy export columns are accepted). */
  csv: z.string().max(1_000_000).optional(),
  // 'text': Resuto's heuristic parser of pasted or uploaded menu text (no model involved; Studio menu extraction).
  source: z.enum(['csv', 'foodics', 'odoo', 'ai', 'text']).default('csv'),
  key: idempotencyKey.optional(),
}).refine((b) => !!b.rows !== !!b.csv, { message: 'Send either rows or csv' });
export type MenuImportRequest = z.infer<typeof menuImportRequest>;

export interface MenuImportPreviewRow {
  row: number;
  action: 'create' | 'update';
  productId: string | null;
  errors: string[];
  warnings: string[];
  item: { externalId: string | null; name: string; nameAr: string | null; category: string; description: string | null; priceMinor: number; station: string; allergens: string[]; available: boolean };
}
export interface MenuImportPreview {
  source: string;
  rows: MenuImportPreviewRow[];
  summary: { total: number; create: number; update: number; errors: number; newCategories: string[] };
}

/** RFC 4180 CSV parser (port of legacy data-tools.parseCSV): quoted fields, CRLF, BOM. */
export function parseCsv(input: string): Array<Record<string, string>> {
  if (input.length > 1_000_000) throw new RangeError('CSV must be smaller than 1 MB.');
  const rows: string[][] = [];
  let row: string[] = [], value = '', quoted = false;
  for (let i = 0; i < input.length; i++) {
    const c = input[i];
    if (c === '"') {
      if (quoted && input[i + 1] === '"') { value += '"'; i++; } else quoted = !quoted;
    } else if (c === ',' && !quoted) { row.push(value); value = ''; }
    else if ((c === '\n' || c === '\r') && !quoted) {
      if (c === '\r' && input[i + 1] === '\n') i++;
      row.push(value);
      if (row.some((x) => x.trim())) rows.push(row);
      row = []; value = '';
    } else value += c;
  }
  if (quoted) throw new RangeError('CSV has an unclosed quoted field.');
  row.push(value);
  if (row.some((x) => x.trim())) rows.push(row);
  const columns = (rows.shift() ?? []).map((x) => x.replace(/^﻿/, '').trim());
  if (new Set(columns).size !== columns.length) throw new RangeError('Duplicate CSV columns.');
  return rows.map((r, i) => {
    if (r.length !== columns.length) throw new RangeError(`Incorrect column count at row ${i + 2}`);
    return Object.fromEntries(columns.map((c, n) => [c, r[n] ?? '']));
  });
}

/** Escapes a CSV cell against formula injection (legacy toCSV behaviour). */
export function csvCell(v: unknown): string {
  let s = typeof v === 'object' && v !== null ? JSON.stringify(v) : String(v ?? '');
  if (/^[=+\-@\t\r]/.test(s)) s = `'${s}`;
  return `"${s.replaceAll('"', '""')}"`;
}
export const toCsv = (rows: Array<Record<string, unknown>>) => {
  if (!rows.length) return '';
  const keys = Object.keys(rows[0]!);
  return [keys, ...rows.map((r) => keys.map((k) => r[k]))].map((r) => r.map(csvCell).join(',')).join('\r\n');
};

// ---------------------------------------------------------------------------
// Response shapes
// ---------------------------------------------------------------------------
export interface ModifierOption { id: string; groupId: string; name: string; nameAr: string | null; priceDeltaMinor: number; isDefault: boolean; isAvailable: boolean; sortOrder: number }
export interface ModifierGroup { id: string; name: string; nameAr: string | null; minSelect: number; maxSelect: number; isActive: boolean; options: ModifierOption[] }
export interface ProductBranchSettingView {
  branchId: string;
  /** Offered at this branch. */
  isAvailable: boolean;
  priceOverrideMinor: number | null; stockQty: number | null;
  /** Temporarily sold out (86), effective now. */
  soldOut?: boolean; soldOutUntil?: string | null; soldOutReason?: string | null;
}
export interface Product {
  id: string; categoryId: string; name: string; nameAr: string | null; description: string | null; descriptionAr: string | null;
  priceMinor: number; costMinor: number | null; currency: string; station: string; prepMinutes: number | null; spiceLevel: number;
  dietary: string[]; allergens: string[]; ingredients: string[]; calories: number | null; imageUrl: string | null; imageMediaId: string | null;
  isActive: boolean; trackStock: boolean; sortOrder: number; externalRef: string | null; version: number;
  branchSettings: ProductBranchSettingView[]; modifierGroupIds: string[];
  /**
   * Portions the ingredients on hand can make, per active branch (the scarcest ingredient of the recipe decides,
   * gallery PAR-03). Null when the dish has no recipe, so its portions are not tracked by ingredients. Left out
   * (undefined) when the caller may not read stock: the counts are derived from stock levels, so GET /o/:orgId/menu
   * includes them only for inventory:read or kitchen:operate (owner, admin, manager, kitchen), not for menu:read-only
   * roles such as cashier, waiter or marketing.
   */
  recipePortions?: Array<{ branchId: string; portions: number }> | null;
}
export interface Category { id: string; menuId: string; name: string; nameAr: string | null; description: string | null; defaultStation: string | null; sortOrder: number; isActive: boolean }
export interface MenuEditorView {
  menus: Array<{ id: string; name: string; nameAr: string | null; branchId: string | null; isActive: boolean }>;
  categories: Category[];
  products: Product[];
  modifierGroups: ModifierGroup[];
  stations: string[];
  currency: string;
}

export interface PublicMenuOption { id: string; name: string; nameAr: string | null; priceDeltaMinor: number; available: boolean }
export interface PublicMenuGroup { id: string; name: string; nameAr: string | null; minSelect: number; maxSelect: number; options: PublicMenuOption[] }
export interface PublicMenuProduct {
  id: string; name: string; nameAr: string | null; description: string | null; descriptionAr: string | null; priceMinor: number;
  /** A WebP derivative at least 640 px wide when one exists (CR-12), else the original. */
  imageUrl: string | null;
  /** `url 320w, url 640w, url 1280w` over the stored derivatives (null without derivatives). */
  imageSrcSet?: string | null;
  /** Original dimensions, for reserving the image box (no layout shift). */
  imageWidth?: number | null; imageHeight?: number | null;
  allergens: string[]; dietary: string[]; spiceLevel: number;
  /** false = shown as sold out (86 or tracked stock at 0); see SOLD_OUT_DISPLAY. */
  available: boolean;
  /** Why it is unavailable: 'sold_out' (86) or 'out_of_stock'. */
  unavailableReason?: 'sold_out' | 'out_of_stock' | null;
  prepMinutes: number | null;
  modifierGroups: PublicMenuGroup[];
}
export interface PublicBranch {
  id: string; code: string; name: string; nameAr: string | null; acceptsDineIn: boolean; acceptsPickup: boolean; acceptsDelivery: boolean;
  acceptsReservations: boolean; deliveryFeeMinor: number; minOrderMinor: number; address: string | null; city: string | null; phone: string | null;
}
export interface PublicMenu {
  org: {
    name: string; nameAr: string | null; currency: 'EGP' | 'SAR'; slug: string;
    /** Links shown as icons (21-ONB); only valid https links on each network's hosts. */
    socialLinks?: SocialLinks;
  };
  branch: PublicBranch;
  branches: PublicBranch[];
  categories: Array<{ id: string; name: string; nameAr: string | null; products: PublicMenuProduct[] }>;
}
